examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var current: String? = {{current}}
@State private var showsSupport = false

/// One icon button of the rail: named for VoiceOver, with a dot when something is new, and a dark plate and a bar when current.
private func railButton(_ label: String, systemImage: String, key: String? = nil, hasDot: Bool = false, unread: Int? = nil, hint: String? = nil, action: @escaping () -> Void = {}) -> some View {
    Button {
        if let key { current = key }
        action()
    } label: {
        Image(systemName: systemImage)
            .foregroundStyle(theme.colors.accentOnSolid)
            .frame(width: 40, height: 40)
            .overlay(alignment: .topTrailing) {
                if hasDot {
                    Circle().fill(theme.colors.accentOnSolid).frame(width: 8, height: 8)
                }
            }
            .background {
                if key != nil && current == key {
                    RoundedRectangle(cornerRadius: 8, style: .continuous).fill(theme.colors.accentSolidActive)
                }
            }
            .overlay(alignment: .leading) {
                if key != nil && current == key {
                    Capsule().fill(theme.colors.accentOnSolid).frame(width: 3, height: 24).offset(x: -2)
                }
            }
            .frame(minWidth: 44, minHeight: 44)
    }
    .buttonStyle(.plain)
    .accessibilityLabel(label)
    .accessibilityValue(unread.map { "\($0) unread" } ?? "")
    .accessibilityHint(hint ?? "")
    .accessibilityAddTraits(key != nil && current == key ? .isSelected : [])
}

